import { GitIndexManager } from '../managers/GitIndexManager.ts'
import type { Worktree } from './Worktree.ts'
import type { GitIndex } from '../git/index/GitIndex.ts'

/**
 * StagingArea - Wrapper around GitIndexManager providing Worktree-aware access to the staging area
 * Each worktree has its own staging area (index file) bound to its gitdir
 */
export class StagingArea {
  private readonly worktree: Worktree

  constructor(worktree: Worktree) {
    this.worktree = worktree
  }

  /**
   * Gets the worktree this staging area belongs to
   */
  getWorktree(): Worktree {
    return this.worktree
  }

  /**
   * Reads the current index (staging area) for this worktree
   */
  async read(allowUnmerged: boolean = true): Promise<GitIndex> {
    const gitdir = await this.worktree.getGitdir()
    const repo = this.worktree.repository
    return await GitIndexManager.acquire(
      { 
        fs: repo.fs, 
        gitdir, 
        cache: repo.cache, 
        allowUnmerged 
      },
      async (index) => {
        return index
      }
    )
  }

  /**
   * Writes the index back to disk
   * If a GitIndex is provided, its state will be copied to the cached index and marked as dirty.
   * If no index is provided, the cached index will be marked as dirty if it has been modified.
   */
  async write(index?: GitIndex): Promise<void> {
    const gitdir = await this.worktree.getGitdir()
    const repo = this.worktree.repository
    await GitIndexManager.acquire(
      { 
        fs: repo.fs, 
        gitdir, 
        cache: repo.cache, 
        allowUnmerged: true 
      },
      async (cachedIndex) => {
        if (index && index !== cachedIndex) {
          // Copy state from provided index to cached index
          // Clear existing entries
          cachedIndex.clear()
          // Copy all entries including all stages (use entriesFlat to get all stages)
          for (const entry of index.entriesFlat) {
            cachedIndex.insert({
              filepath: entry.path,
              oid: entry.oid,
              stats: {
                ctimeSeconds: entry.ctimeSeconds,
                ctimeNanoseconds: entry.ctimeNanoseconds,
                mtimeSeconds: entry.mtimeSeconds,
                mtimeNanoseconds: entry.mtimeNanoseconds,
                dev: entry.dev,
                ino: entry.ino,
                mode: entry.mode,
                uid: entry.uid,
                gid: entry.gid,
                size: entry.size,
              },
              stage: entry.flags.stage,
            })
          }
        }
        // Mark as dirty so it gets saved
        ;(cachedIndex as { _dirty?: boolean })._dirty = true
      }
    )
  }

  /**
   * Acquires the index for exclusive access and executes a callback
   * This ensures thread-safe access to the index
   */
  async acquire<T>(
    callback: (index: GitIndex) => Promise<T> | T,
    allowUnmerged: boolean = true
  ): Promise<T> {
    const gitdir = await this.worktree.getGitdir()
    const repo = this.worktree.repository
    return await GitIndexManager.acquire(
      { 
        fs: repo.fs, 
        gitdir, 
        cache: repo.cache, 
        allowUnmerged 
      },
      callback
    )
  }

  /**
   * Clears all entries from the staging area
   */
  async clear(): Promise<void> {
    await this.acquire(async (index) => {
      index.clear()
      ;(index as { _dirty?: boolean })._dirty = true
    })
  }
}



