/**
 * Reads the Git index directly from .git/index file
 * This is the single source of truth - reads directly from disk
 * 
 * @param fs - File system client
 * @param gitdir - Path to .git directory
 * @param cache - Optional cache object for performance
 * @returns The parsed GitIndex object
 */
import { GitIndex } from './GitIndex.ts'
import { normalizeFs } from '../../utils/normalizeFs.ts'
import { join, normalize as normalizePath } from '../../core-utils/GitPath.ts'
import type { FsClient } from '../../models/FileSystem.ts'

export async function readIndex({
  fs,
  gitdir,
  cache,
}: {
  fs: FsClient
  gitdir: string
  cache?: Record<string, unknown>
}): Promise<GitIndex> {
  const normalizedFs = normalizeFs(fs)
  // Normalize gitdir to ensure consistent cache keys
  const normalizedGitdir = normalizePath(gitdir)
  const indexPath = join(normalizedGitdir, 'index')
  
  // Simple cache: check if we have a cached index and if file hasn't changed
  // Use normalized gitdir for cache key to ensure consistency
  const cacheKey = `index:${normalizedGitdir}`
  if (cache) {
    const cached = cache[cacheKey] as { index: GitIndex, mtime: number | null } | undefined
    if (cached?.index) {
      try {
        const stat = await normalizedFs.lstat(indexPath)
        const mtime = stat.mtimeSeconds * 1000 + (stat.mtimeNanoseconds || 0) / 1000000
        if (cached.mtime === mtime) {
          return cached.index
        }
      } catch {
        // File doesn't exist or changed - clear cache
        delete cache[cacheKey]
      }
    }
  }
  
  // Read from disk
  try {
    const indexBuffer = await normalizedFs.read(indexPath)
    const index = indexBuffer.length === 0 
      ? new GitIndex() 
      : await GitIndex.from(indexBuffer as Buffer | Uint8Array)
    
    // Update cache
    if (cache) {
      try {
        const stat = await normalizedFs.lstat(indexPath)
        cache[cacheKey] = {
          index,
          mtime: stat.mtimeSeconds * 1000 + (stat.mtimeNanoseconds || 0) / 1000000
        }
      } catch {
        cache[cacheKey] = { index, mtime: null }
      }
    }
    
    return index
  } catch {
    // Index doesn't exist - return empty index
    const index = new GitIndex()
    if (cache) {
      cache[cacheKey] = { index, mtime: null }
    }
    return index
  }
}



