/**
 * Writes the Git index directly to .git/index file
 * This is the single source of truth - writes directly to disk
 * 
 * @param fs - File system client
 * @param gitdir - Path to .git directory
 * @param index - The GitIndex object to write
 * @param cache - Optional cache object to update after write
 */
import { GitIndex } from './GitIndex.ts'
import { normalizeFs } from '../../utils/normalizeFs.ts'
import { join, normalize as normalizePath } from '../../core-utils/GitPath.ts'
import type { FsClient } from '../../models/FileSystem.ts'
import type { Stat } from '../../models/FileSystem.ts'

export async function writeIndex({
  fs,
  gitdir,
  index,
  cache,
}: {
  fs: FsClient
  gitdir: string
  index: GitIndex
  cache?: Record<string, unknown>
}): Promise<void> {
  const normalizedFs = normalizeFs(fs)
  // Normalize gitdir to ensure consistent cache keys
  const normalizedGitdir = normalizePath(gitdir)
  const indexPath = join(normalizedGitdir, 'index')
  
  const buffer = await index.toObject()
  await normalizedFs.write(indexPath, buffer)
  
  // Ensure write is flushed to disk
  if (normalizedFs.sync) {
    await normalizedFs.sync(indexPath)
  }
  
  // Get the file stat AFTER writing to ensure we have the correct mtime
  let stat: Stat | null = null
  try {
    stat = await normalizedFs.lstat(indexPath)
  } catch {
    // File doesn't exist (shouldn't happen, but handle it)
  }
  
  // Update both cache systems:
  // 1. Simple string-based cache for readIndexDirect()
  // 2. GitIndexManager's Symbol-based cache (for backward compatibility)
  if (cache) {
    // Update simple cache with the index and current mtime
    const cacheKey = `index:${normalizedGitdir}`
    if (stat) {
      cache[cacheKey] = {
        index,
        mtime: stat.mtimeSeconds * 1000 + (stat.mtimeNanoseconds || 0) / 1000000
      }
    } else {
      cache[cacheKey] = { index, mtime: null }
    }
    
    // Also update GitIndexManager cache for backward compatibility
    // This ensures that code still using GitIndexManager sees the updated index
    // Import the IndexCache Symbol from GitIndexManager to ensure we use the same instance
    const { IndexCache } = await import('../../managers/GitIndexManager.ts')
    const indexCacheKey = IndexCache as unknown as string
    
    if (!cache[indexCacheKey]) {
      // Create cache if it doesn't exist (same structure as GitIndexManager)
      cache[indexCacheKey] = {
        map: new Map(),
        stats: new Map(),
      }
    }
    const theIndexCache = cache[indexCacheKey] as { map: Map<string, GitIndex>, stats: Map<string, Stat | null> }
    const normalizedFilepath = normalizePath(indexPath)
    
    // Update GitIndexManager cache with the index and current stat
    theIndexCache.map.set(normalizedFilepath, index)
    if (stat) {
      theIndexCache.stats.set(normalizedFilepath, stat)
    } else {
      theIndexCache.stats.set(normalizedFilepath, null)
    }
  }
}



