import AsyncLock from 'async-lock'

import { UnmergedPathsError } from '../errors/UnmergedPathsError.ts'
import { GitIndex } from "../git/index/GitIndex.ts"
import { compareStats } from "../utils/compareStats.ts"
import { normalizeFs } from "../utils/normalizeFs.ts"
import { normalize as normalizePath } from "../core-utils/GitPath.ts"
import { getStateMutationStream } from "../core-utils/StateMutationStream.ts"
import type { FsClient, Stat } from "../models/FileSystem.ts"

let lock: AsyncLock | null = null

// Export IndexCache Symbol so it can be shared with other modules
export const IndexCache = Symbol('IndexCache')

type IndexCacheData = {
  map: Map<string, GitIndex>
  stats: Map<string, Stat | null>
}

/**
 * Creates a cache object to store GitIndex and file stats.
 */
function createCache(): IndexCacheData {
  return {
    map: new Map(),
    stats: new Map(),
  }
}

/**
 * Updates the cached index file by reading the file system and parsing the Git index.
 */
async function updateCachedIndexFile(
  fs: FsClient,
  filepath: string,
  cache: IndexCacheData
): Promise<void> {
  const normalizedFs = normalizeFs(fs)
  let stat: Stat | null
  let rawIndexFile: Buffer | Uint8Array | string | null
  
  try {
    [stat, rawIndexFile] = await Promise.all([
      normalizedFs.lstat(filepath),
      normalizedFs.read(filepath),
    ])
  } catch {
    // Index file doesn't exist - create empty index
    stat = null
    rawIndexFile = null
  }

  let index: GitIndex
  if (!rawIndexFile) {
    // Index file doesn't exist - create empty GitIndex
    index = new GitIndex()
  } else if (Buffer.isBuffer(rawIndexFile) && rawIndexFile.length === 0) {
    // Empty index file - this is an error condition, let GitIndex.from throw
    // Don't catch this error - it should propagate to the caller
    index = await GitIndex.from(rawIndexFile)
  } else {
    // Try to parse the index file
    // If we get a checksum error, it might be because the file is being written
    // In that case, try to use the cached version if available, or wait and retry
    try {
      index = await GitIndex.from(rawIndexFile as Buffer | Uint8Array)
    } catch (error: any) {
      // If it's a checksum error and we have a cached index, use the cached version
      // This handles race conditions where the file is read while being written
      if (error?.code === 'InternalError' && error?.data?.message?.includes('Invalid checksum')) {
        const normalizedFilepath = normalizePath(filepath)
        const cachedIndex = cache.map.get(normalizedFilepath)
        if (cachedIndex) {
          console.log(`[DEBUG updateCachedIndexFile] Checksum error detected, using cached index instead`)
          index = cachedIndex
          // Update stat to current time to prevent immediate re-read
          cache.stats.set(normalizedFilepath, stat as Stat | null)
          return
        }
        // If no cached index, wait a bit and retry once
        // But only if we're sure the file exists and might be in the process of being written
        await new Promise(resolve => setTimeout(resolve, 100))
        try {
          const retryRawIndexFile = await normalizedFs.read(filepath)
          index = await GitIndex.from(retryRawIndexFile as Buffer | Uint8Array)
        } catch (retryError) {
          // If retry also fails, check if we can create an empty index
          // This handles the case where the index file is corrupted
          console.log(`[DEBUG updateCachedIndexFile] Retry also failed, creating empty index`)
          index = new GitIndex()
          // Store the empty index in cache before returning
          const normalizedFilepath = normalizePath(filepath)
          cache.map.set(normalizedFilepath, index)
          cache.stats.set(normalizedFilepath, stat as Stat | null)
          return
        }
      } else {
        // For other errors, propagate them
        throw error
      }
    }
  }
  
  // cache the GitIndex object so we don't need to re-read it every time.
  // Use normalized filepath as the key to ensure consistency
  const normalizedFilepath = normalizePath(filepath)
  
  // DEBUG: Log when cache is being overwritten (temporary)
  const oldIndex = cache.map.get(normalizedFilepath)
  const oldFilepaths = oldIndex ? Array.from(oldIndex.entriesMap.keys()) : []
  const newFilepaths = Array.from(index.entriesMap.keys())
  if (oldFilepaths.length !== newFilepaths.length || oldFilepaths.some((f, i) => f !== newFilepaths[i])) {
    console.log(`[DEBUG updateCachedIndexFile] OVERWRITING CACHE: old=${oldFilepaths}, new=${newFilepaths}`)
  }
  
  cache.map.set(normalizedFilepath, index)
  // Save the stat data for the index so we know whether the cached file is stale (modified by an outside process).
  cache.stats.set(normalizedFilepath, stat as Stat | null)
}

/**
 * Determines whether the cached index file is stale by comparing file stats.
 */
async function isIndexStale(
  fs: FsClient,
  filepath: string,
  cache: IndexCacheData
): Promise<boolean> {
  // Use normalized filepath for cache lookup
  const normalizedFilepath = normalizePath(filepath)
  const savedStats = cache.stats.get(normalizedFilepath)
  if (savedStats === undefined) return true
  if (savedStats === null) return false

  const normalizedFs = normalizeFs(fs)
  const currStats = await normalizedFs.lstat(filepath)
  if (currStats === null) return false
  return compareStats(savedStats, currStats as Stat)
}

export class GitIndexManager {
  /**
   * Manages access to the Git index file, ensuring thread-safe operations and caching.
   */
  static async acquire<T>({
    fs,
    gitdir,
    cache,
    allowUnmerged = true,
  }: {
    fs: FsClient
    gitdir: string
    cache: Record<string, unknown>
    allowUnmerged?: boolean
  }, closure: (index: GitIndex) => Promise<T> | T): Promise<T> {
    const cacheKey = IndexCache as unknown as string
    if (!cache[cacheKey]) {
      cache[cacheKey] = createCache()
    }
    
    // DEBUG: Log cache key and cache state (temporary)
    console.log(`[DEBUG GitIndexManager.acquire] Cache key: ${String(cacheKey)}, cache has key: ${!!cache[cacheKey]}`)
    
    // Normalize gitdir path to ensure consistent cache keys
    // This ensures that add() and stash() use the same cache entry even if
    // one uses a relative path and the other uses an absolute path
    const normalizedGitdir = normalizePath(gitdir)
    const filepath = `${normalizedGitdir}/index`

    if (lock === null) lock = new AsyncLock({ 
      maxPending: Infinity,
      timeout: 30000, // 30 second timeout to prevent deadlocks
    })
    let result: T
    let unmergedPaths: string[] = []
    await lock.acquire(filepath, async () => {
      // Acquire a file lock while we're reading the index
      // to make sure other processes aren't writing to it
      // simultaneously, which could result in a corrupted index.
      // const fileLock = await Lock(filepath)
      const theIndexCache = cache[cacheKey] as IndexCacheData
      // Use normalized filepath for cache lookup
      const normalizedFilepath = normalizePath(filepath)
      const cachedIndex = theIndexCache.map.get(normalizedFilepath)
      
      // DEBUG: Log cache lookup (temporary)
      const cacheMapSize = theIndexCache.map.size
      const cacheHasEntry = theIndexCache.map.has(normalizedFilepath)
      console.log(`[DEBUG GitIndexManager.acquire] Cache lookup: normalizedFilepath=${normalizedFilepath}, cacheMapSize=${cacheMapSize}, hasEntry=${cacheHasEntry}, cachedIndex=${cachedIndex ? 'exists' : 'null'}`)
      
      // CRITICAL: If we have a cached index that is dirty, use it instead of reading from disk
      // This ensures that staged changes from add() are visible to subsequent operations like stash()
      // The dirty flag indicates the cached index is newer than what's on disk
      const cachedIndexIsDirty = cachedIndex && (cachedIndex as { _dirty?: boolean })._dirty
      
      // DEBUG: Log cache state (temporary)
      if (cachedIndex) {
        const cachedFilepaths = Array.from(cachedIndex.entriesMap.keys())
        console.log(`[DEBUG GitIndexManager.acquire] Cached index filepaths:`, cachedFilepaths, `dirty:`, cachedIndexIsDirty)
      }
      
      // CRITICAL FIX: Don't read from disk if we have a cached index, even if it's not dirty
      // The cache should always be the source of truth after a write operation
      // Only read from disk if:
      // 1. We don't have a cached index, OR
      // 2. The cached index is not dirty AND the disk file is newer (stale check)
      // But we should NEVER overwrite a cached index that was just written
      if (!cachedIndex) {
        // No cached index - read from disk
        console.log(`[DEBUG GitIndexManager.acquire] No cached index - reading from disk`)
        try {
          await updateCachedIndexFile(fs, filepath, theIndexCache)
        } catch (error: any) {
          // If we get a checksum error and there's no cached index, this is a real error
          // But if we're inside a lock and the file is being written, we might get a checksum error
          // In that case, wait a bit and retry
          if (error?.code === 'InternalError' && error?.data?.message?.includes('Invalid checksum')) {
            console.log(`[DEBUG GitIndexManager.acquire] Checksum error on initial read, waiting and retrying`)
            await new Promise(resolve => setTimeout(resolve, 100))
            try {
              await updateCachedIndexFile(fs, filepath, theIndexCache)
            } catch (retryError) {
              // If retry also fails, create an empty index as a fallback
              // This handles the case where the index file is corrupted
              console.log(`[DEBUG GitIndexManager.acquire] Retry also failed, creating empty index`)
              const emptyIndex = new GitIndex()
              theIndexCache.map.set(normalizedFilepath, emptyIndex)
              // Update stats to null to indicate index doesn't exist on disk
              theIndexCache.stats.set(normalizedFilepath, null)
            }
          } else {
            throw error
          }
        }
      } else if (cachedIndexIsDirty) {
        // Cached index is dirty - use it (don't read from disk)
        console.log(`[DEBUG GitIndexManager.acquire] Using dirty cached index (not reading from disk)`)
      } else {
        // Cached index exists and is not dirty - check if disk is newer
        const isStale = await isIndexStale(fs, filepath, theIndexCache)
        // DEBUG: Log stale check result (temporary)
        const savedStats = theIndexCache.stats.get(normalizedFilepath)
        const currStats = await normalizeFs(fs).lstat(filepath)
        console.log(`[DEBUG GitIndexManager.acquire] Stale check: isStale=${isStale}, savedStats=${savedStats ? 'exists' : 'null'}, currStats=${currStats ? 'exists' : 'null'}`)
        
        if (isStale) {
          // Disk is newer - but be careful: if we just wrote the index, the cache is the source of truth
          // Only read from disk if the disk file is significantly newer (more than a few milliseconds)
          // This prevents reading a partially-written file that could have an invalid checksum
          const savedMtime = savedStats?.mtimeSeconds ? savedStats.mtimeSeconds * 1000 + (savedStats.mtimeNanoseconds || 0) / 1000000 : 0
          const currMtime = currStats?.mtimeSeconds ? currStats.mtimeSeconds * 1000 + (currStats.mtimeNanoseconds || 0) / 1000000 : 0
          const timeDiff = currMtime - savedMtime
          
          // Only read from disk if the file is at least 10ms newer (to avoid race conditions)
          // This prevents reading a file that's being written, which could have an invalid checksum
          if (timeDiff > 10) {
            console.log(`[DEBUG GitIndexManager.acquire] Reading from disk - cache is stale (${timeDiff}ms difference)`)
            try {
              await updateCachedIndexFile(fs, filepath, theIndexCache)
            } catch (error: any) {
              // If we get a checksum error, use the cached version instead
              // This handles race conditions where the file is read while being written
              if (error?.code === 'InternalError' && error?.data?.message?.includes('Invalid checksum')) {
                console.log(`[DEBUG GitIndexManager.acquire] Checksum error on stale read, using cached index instead`)
                // Keep using the cached index - don't update it
              } else {
                throw error
              }
            }
          } else {
            // Use cached version - disk file might be partially written or have invalid checksum
            console.log(`[DEBUG GitIndexManager.acquire] Using cached index (disk file too recent, might be partially written)`)
          }
        } else {
          // Cache is up to date - use it
          console.log(`[DEBUG GitIndexManager.acquire] Using cached index (not stale)`)
        }
      }
      
      // Get the index from cache (either the dirty one or the one we just read from disk)
      const index = theIndexCache.map.get(normalizedFilepath)
      if (!index) {
        throw new Error('Index not found in cache')
      }
      
      // DEBUG: Log final index state (temporary)
      const finalFilepaths = Array.from(index.entriesMap.keys())
      console.log(`[DEBUG GitIndexManager.acquire] Final index filepaths:`, finalFilepaths)
      unmergedPaths = index.unmergedPaths

      // Check for unmerged paths and throw error if found and allowUnmerged is false
      // This MUST happen before calling the closure to match native git behavior
      if (unmergedPaths.length > 0 && !allowUnmerged) {
        throw new UnmergedPathsError(unmergedPaths)
      }

      result = await closure(index)
      if ((index as { _dirty?: boolean })._dirty) {
        // Acquire a file lock while we're writing the index file
        // let fileLock = await Lock(filepath)
        const normalizedFs = normalizeFs(fs)
        const buffer = await index.toObject()
        // CRITICAL: Write the index file atomically to prevent checksum errors
        // The buffer already includes the checksum at the end (from serialize function)
        // Write it in one operation to ensure the file is never in a partially-written state
        await normalizedFs.write(filepath, buffer)
        // Ensure the write is flushed to disk before proceeding
        // This prevents race conditions where the file is read before the write completes
        if (normalizedFs.sync) {
          await normalizedFs.sync(filepath)
        }
        
        // Record state mutation in central stream
        const mutationStream = getStateMutationStream()
        mutationStream.record({
          type: 'index-write',
          gitdir: normalizedGitdir,
          data: {
            filepath,
            entryCount: index.entries.size,
          },
        })
        
        // Optimistic cache update: Update the cache entry immediately after writing
        // This ensures subsequent reads from the same cache instance see the updated data
        // without needing to re-read from disk
        const normalizedFilepath = normalizePath(filepath)
        // Update the cached index object - create a fresh copy to ensure it's not modified
        // The index object we have is already the updated one, so we just need to ensure
        // it's properly cached and the stat is updated
        theIndexCache.map.set(normalizedFilepath, index)
        // Update cached stat value to reflect the write
        // CRITICAL: Update stat BEFORE clearing dirty flag to ensure cache is consistent
        // Also, mark the index as not dirty AFTER updating the cache, so subsequent reads
        // will use the cached version instead of reading from disk
        const newStat = await normalizedFs.lstat(filepath)
        theIndexCache.stats.set(normalizedFilepath, newStat as Stat | null)
        // Clear dirty flag AFTER cache is updated - this ensures the cache is the source of truth
        ;(index as { _dirty?: boolean })._dirty = false
        
        // DEBUG: Log cache update after write (temporary)
        const updatedFilepaths = Array.from(index.entriesMap.keys())
        const cachedAfterWrite = theIndexCache.map.get(normalizedFilepath)
        const cachedAfterWriteFilepaths = cachedAfterWrite ? Array.from(cachedAfterWrite.entriesMap.keys()) : []
        console.log(`[DEBUG GitIndexManager.acquire] After write, cache updated with filepaths:`, updatedFilepaths)
        console.log(`[DEBUG GitIndexManager.acquire] After write, cached index has filepaths:`, cachedAfterWriteFilepaths)
      } else {
        // Record read operation for auditing
        const mutationStream = getStateMutationStream()
        mutationStream.record({
          type: 'index-read',
          gitdir: normalizedGitdir,
        })
      }
    })

    return result!
  }
}



