import { AmbiguousError } from '../errors/AmbiguousError.ts'
import { NotFoundError } from '../errors/NotFoundError.ts'
import { expandOidLoose } from './expandOidLoose.ts'
import { expandOidPacked } from './expandOidPacked.ts'
import { _readObject as readObject } from './readObject.ts'
import type { FsClient } from "../models/FileSystem.ts"

export async function _expandOid({
  fs,
  cache,
  gitdir,
  oid: short,
}: {
  fs: FsClient
  cache: Record<string, unknown>
  gitdir: string
  oid: string
}): Promise<string> {
  // Curry the current read method so that the packfile un-deltification
  // process can acquire external ref-deltas.
  const getExternalRefDelta = async (oid: string): Promise<{ type: string; object: Buffer }> => {
    const result = await readObject({ fs, cache, gitdir, oid })
    return {
      type: result.type || '',
      object: result.object,
    }
  }

  const results = await expandOidLoose({ fs, gitdir, oid: short })
  const packedOids = await expandOidPacked({
    fs,
    cache,
    gitdir,
    oid: short,
    getExternalRefDelta,
  })
  // Objects can exist in a pack file as well as loose, make sure we only get a list of unique oids.
  for (const packedOid of packedOids) {
    if (results.indexOf(packedOid) === -1) {
      results.push(packedOid)
    }
  }

  if (results.length === 1) {
    return results[0]
  }
  if (results.length > 1) {
    throw new AmbiguousError('oids', short, results)
  }
  throw new NotFoundError(`an object matching "${short}"`)
}



// ==============================================================================
// File: src\storage\expandOidLoose.ts
// ==============================================================================

import { normalizeFs } from "../utils/normalizeFs.ts"
import type { FsClient } from "../models/FileSystem.ts"

export async function expandOidLoose({
  fs,
  gitdir,
  oid: short,
}: {
  fs: FsClient
  gitdir: string
  oid: string
}): Promise<string[]> {
  const normalizedFs = normalizeFs(fs)
  const prefix = short.slice(0, 2)
  const objectsSuffixes = await normalizedFs.readdir(`${gitdir}/objects/${prefix}`)
  if (!objectsSuffixes) {
    return []
  }
  return objectsSuffixes
    .map(suffix => `${prefix}${suffix}`)
    .filter(_oid => _oid.startsWith(short))
}



// ==============================================================================
// File: src\storage\expandOidPacked.ts
// ==============================================================================

import { InternalError } from '../errors/InternalError.ts'
import { iteratePackfiles } from './packfileIterator.ts'
import type { FsClient } from "../models/FileSystem.ts"

export async function expandOidPacked({
  fs,
  cache,
  gitdir,
  oid: short,
  getExternalRefDelta,
}: {
  fs: FsClient
  cache: Record<string, unknown>
  gitdir: string
  oid: string
  getExternalRefDelta?: (oid: string) => Promise<{ type: string; object: Buffer }>
}): Promise<string[]> {
  const results: string[] = []
  await iteratePackfiles({
    fs,
    cache,
    gitdir,
    getExternalRefDelta,
    callback: async (p) => {
      if (p.error) throw new InternalError(p.error)
      // Search through the list of oids in the packfile
      for (const oid of p.offsets.keys()) {
        if (oid.startsWith(short)) results.push(oid)
      }
      return null // Continue iterating
    },
  })
  return results
}



