// File: src\utils\formatAuthor.ts
// ==============================================================================

import type { Author } from "../models/GitCommit.ts"

export const formatAuthor = ({ name, email, timestamp, timezoneOffset }: Author): string => {
  const formattedOffset = formatTimezoneOffset(timezoneOffset)
  return `${name} <${email}> ${timestamp} ${formattedOffset}`
}

// The amount of effort that went into crafting these cases to handle
// -0 (just so we don't lose that information when parsing and reconstructing)
// but can also default to +0 was extraordinary.

const formatTimezoneOffset = (minutes: number): string => {
  const sign = simpleSign(negateExceptForZero(minutes))
  const absMinutes = Math.abs(minutes)
  const hours = Math.floor(absMinutes / 60)
  const remainingMinutes = absMinutes - hours * 60
  let strHours = String(hours)
  let strMinutes = String(remainingMinutes)
  if (strHours.length < 2) strHours = '0' + strHours
  if (strMinutes.length < 2) strMinutes = '0' + strMinutes
  return (sign === -1 ? '-' : '+') + strHours + strMinutes
}

const simpleSign = (n: number): number => {
  return Math.sign(n) || (Object.is(n, -0) ? -1 : 1)
}

const negateExceptForZero = (n: number): number => {
  return n === 0 ? n : -n
}



// ==============================================================================
// File: src\utils\formatInfoRefs.ts
// ==============================================================================

import type { ServerRef } from "../managers/GitRefManager.ts"

type RemoteRefs = {
  refs: Map<string, string>
  symrefs: Map<string, string>
}

export function formatInfoRefs(remote: RemoteRefs, prefix: string, symrefs: boolean, peelTags: boolean): ServerRef[] {
  const refs: ServerRef[] = []
  for (const [key, value] of remote.refs) {
    if (prefix && !key.startsWith(prefix)) continue

    if (key.endsWith('^{}')) {
      if (peelTags) {
        const _key = key.replace('^{}', '')
        // Peeled tags are almost always listed immediately after the original tag
        const last = refs[refs.length - 1]
        const r = last && last.ref === _key ? last : refs.find(x => x.ref === _key)
        if (r === undefined) {
          throw new Error('I did not expect this to happen')
        }
        r.peeled = value
      }
      continue
    }
    const ref: ServerRef = { ref: key, oid: value }
    if (symrefs) {
      if (remote.symrefs.has(key)) {
        ref.target = remote.symrefs.get(key)
      }
    }
    refs.push(ref)
  }
  return refs
}



