// @ts-check
import { GitTree } from "../models/GitTree.ts"
import { _readObject as readObject } from "../storage/readObject.ts"
import { join } from './join.ts'
import { resolveTree } from './resolveTree.ts'
import type { FsClient } from "../models/FileSystem.ts"

// the empty file content object id
const EMPTY_OID = 'e69de29bb2d1d6434b8b29ae775ad8c2e48c5391'

export async function resolveFileIdInTree({
  fs,
  cache,
  gitdir,
  oid,
  fileId,
}: {
  fs: FsClient
  cache: Record<string, unknown>
  gitdir: string
  oid: string
  fileId: string
}): Promise<string | string[] | undefined> {
  if (fileId === EMPTY_OID) return
  const _oid = oid
  let filepath: string | string[] | undefined
  const result = await resolveTree({ fs, cache, gitdir, oid })
  const tree = result.tree
  if (fileId === result.oid) {
    filepath = ''
  } else {
    filepath = await _resolveFileId({
      fs,
      cache,
      gitdir,
      tree,
      fileId,
      oid: _oid,
    })
    if (Array.isArray(filepath)) {
      if (filepath.length === 0) filepath = undefined
      else if (filepath.length === 1) filepath = filepath[0]
    }
  }
  return filepath
}

async function _resolveFileId({
  fs,
  cache,
  gitdir,
  tree,
  fileId,
  oid,
  filepaths = [],
  parentPath = '',
}: {
  fs: FsClient
  cache: Record<string, unknown>
  gitdir: string
  tree: GitTree
  fileId: string
  oid: string
  filepaths?: string[]
  parentPath?: string
}): Promise<string[]> {
  const walks = tree.entries().map(function (entry) {
    let result: Promise<string[]> | string | undefined
    if (entry.oid === fileId) {
      result = join(parentPath, entry.path)
      filepaths.push(result)
    } else if (entry.type === 'tree') {
      result = readObject({
        fs,
        cache,
        gitdir,
        oid: entry.oid,
      }).then(function ({ object }) {
        return _resolveFileId({
          fs,
          cache,
          gitdir,
          tree: GitTree.from(object),
          fileId,
          oid,
          filepaths,
          parentPath: join(parentPath, entry.path),
        })
      })
    }
    return result
  })

  await Promise.all(walks.filter((w): w is Promise<string[]> => w instanceof Promise))
  return filepaths
}



