import { FIFO } from './FIFO.ts'
import { forAwait } from './forAwait.ts'

// Note: progress messages are designed to be written directly to the terminal,
// so they are often sent with just a carriage return to overwrite the last line of output.
// But there are also messages delimited with newlines.
// I also include CRLF just in case.
function findSplit(str: string): number {
  const r = str.indexOf('\r')
  const n = str.indexOf('\n')
  if (r === -1 && n === -1) return -1
  if (r === -1) return n + 1 // \n
  if (n === -1) return r + 1 // \r
  if (n === r + 1) return n + 1 // \r\n
  return Math.min(r, n) + 1 // \r or \n
}

export function splitLines(input: AsyncIterable<Buffer | Uint8Array> | Iterable<Buffer | Uint8Array>): FIFO {
  const output = new FIFO()
  let tmp = ''
  ;(async () => {
    await forAwait(input, (chunk: Buffer | Uint8Array) => {
      const chunkStr = chunk.toString('utf8')
      tmp += chunkStr
      while (true) {
        const i = findSplit(tmp)
        if (i === -1) break
        output.write(Buffer.from(tmp.slice(0, i)))
        tmp = tmp.slice(i)
      }
    })
    if (tmp.length > 0) {
      output.write(Buffer.from(tmp))
    }
    output.end()
  })()
  return output
}



