// File: src\wire\parseUploadPackRequest.ts
// ==============================================================================

import { GitPktLine } from "../models/GitPktLine.ts"

export type ParseUploadPackRequestResult = {
  capabilities: string[] | null
  wants: string[]
  haves: string[]
  shallows: string[]
  depth?: number
  since?: number
  exclude: string[]
  relative: boolean
  done: boolean
}

export async function parseUploadPackRequest(stream: AsyncIterableIterator<Uint8Array>): Promise<ParseUploadPackRequestResult> {
  const read = GitPktLine.streamReader(stream)
  let done = false
  let capabilities: string[] | null = null
  const wants: string[] = []
  const haves: string[] = []
  const shallows: string[] = []
  let depth: number | undefined
  let since: number | undefined
  const exclude: string[] = []
  let relative = false
  while (!done) {
    const line = await read()
    if (line === true) break
    if (line === null) continue
    const parts = line.toString('utf8').trim().split(' ')
    const [key, value, ...rest] = parts
    if (!capabilities) capabilities = rest
    switch (key) {
      case 'want':
        if (value) wants.push(value)
        break
      case 'have':
        if (value) haves.push(value)
        break
      case 'shallow':
        if (value) shallows.push(value)
        break
      case 'deepen':
        if (value) depth = parseInt(value, 10)
        break
      case 'deepen-since':
        if (value) since = parseInt(value, 10)
        break
      case 'deepen-not':
        if (value) exclude.push(value)
        break
      case 'deepen-relative':
        relative = true
        break
      case 'done':
        done = true
        break
    }
  }
  return {
    capabilities,
    wants,
    haves,
    shallows,
    depth,
    since,
    exclude,
    relative,
    done,
  }
}



// ==============================================================================
// File: src\wire\parseUploadPackResponse.ts
// ==============================================================================

import { InvalidOidError } from "../errors/InvalidOidError.ts"
import { GitSideBand } from "../models/GitSideBand.ts"
import { forAwait } from "../utils/forAwait.ts"
import type { FIFO } from "../utils/FIFO.ts"

export type ParseUploadPackResponseResult = {
  shallows: string[]
  unshallows: string[]
  acks: Array<{ oid: string; status?: string }>
  nak: boolean
  packfile: FIFO
  progress: FIFO
}

export async function parseUploadPackResponse(stream: AsyncIterableIterator<Uint8Array>): Promise<ParseUploadPackResponseResult> {
  const { packetlines, packfile, progress } = GitSideBand.demux(stream)
  const shallows: string[] = []
  const unshallows: string[] = []
  const acks: Array<{ oid: string; status?: string }> = []
  let nak = false
  let done = false
  return new Promise<ParseUploadPackResponseResult>((resolve, reject) => {
    // Parse the response
    forAwait(packetlines as unknown as AsyncIterable<Buffer>, async (data: Buffer) => {
      const line = data.toString('utf8').trim()
      if (line.startsWith('shallow')) {
        const oid = line.slice(-41).trim()
        if (oid.length !== 40) {
          reject(new InvalidOidError(oid))
          return
        }
        shallows.push(oid)
      } else if (line.startsWith('unshallow')) {
        const oid = line.slice(-41).trim()
        if (oid.length !== 40) {
          reject(new InvalidOidError(oid))
          return
        }
        unshallows.push(oid)
      } else if (line.startsWith('ACK')) {
        const parts = line.split(' ')
        const oid = parts[1]
        const status = parts[2]
        if (oid) {
          acks.push({ oid, status })
        }
        if (!status) done = true
      } else if (line.startsWith('NAK')) {
        nak = true
        done = true
      } else {
        done = true
        nak = true
      }
      if (done) {
        const streamAny = stream as any
        streamAny.error
          ? reject(streamAny.error)
          : resolve({ shallows, unshallows, acks, nak, packfile, progress })
      }
    }).finally(() => {
      if (!done) {
        const streamAny = stream as any
        streamAny.error
          ? reject(streamAny.error)
          : resolve({ shallows, unshallows, acks, nak, packfile, progress })
      }
    })
  })
}



// ==============================================================================
// File: src\wire\writeListRefsRequest.ts
// ==============================================================================

import { GitPktLine } from "../models/GitPktLine.ts"
import { pkg } from "../utils/pkg.ts"

export async function writeListRefsRequest({
  prefix,
  symrefs = false,
  peelTags = false,
}: {
  prefix?: string
  symrefs?: boolean
  peelTags?: boolean
}): Promise<Buffer[]> {
  const packstream: Buffer[] = []
  // command
  packstream.push(GitPktLine.encode('command=ls-refs\n'))
  // capability-list
  packstream.push(GitPktLine.encode(`agent=${pkg.agent}\n`))
  // [command-args]
  if (peelTags || symrefs || prefix) {
    packstream.push(GitPktLine.delim())
  }
  if (peelTags) packstream.push(GitPktLine.encode('peel'))
  if (symrefs) packstream.push(GitPktLine.encode('symrefs'))
  if (prefix) packstream.push(GitPktLine.encode(`ref-prefix ${prefix}`))
  packstream.push(GitPktLine.flush())
  return packstream
}



// ==============================================================================
// File: src\wire\writeReceivePackRequest.ts
// ==============================================================================

import { GitPktLine } from "../models/GitPktLine.ts"

export type RefTriplet = {
  oldoid: string
  oid: string
  fullRef: string
}

export async function writeReceivePackRequest({
  capabilities = [],
  triplets = [],
}: {
  capabilities?: string[]
  triplets?: RefTriplet[]
}): Promise<Buffer[]> {
  const packstream: Buffer[] = []
  let capsFirstLine = `\x00 ${capabilities.join(' ')}`
  for (const trip of triplets) {
    packstream.push(
      GitPktLine.encode(
        `${trip.oldoid} ${trip.oid} ${trip.fullRef}${capsFirstLine}\n`
      )
    )
    capsFirstLine = ''
  }
  packstream.push(GitPktLine.flush())
  return packstream
}



// ==============================================================================
// File: src\wire\writeRefsAdResponse.ts
// ==============================================================================

import { GitPktLine } from "../models/GitPktLine.ts"
import { pkg } from "../utils/pkg.ts"

export async function writeRefsAdResponse({
  capabilities,
  refs,
  symrefs,
}: {
  capabilities: Set<string> | string[]
  refs: Map<string, string> | Record<string, string>
  symrefs: Map<string, string> | Record<string, string>
}): Promise<Buffer[]> {
  const stream: Buffer[] = []
  // Compose capabilities string
  let syms = ''
  const symrefsEntries = symrefs instanceof Map ? symrefs.entries() : Object.entries(symrefs)
  for (const [key, value] of symrefsEntries) {
    syms += `symref=${key}:${value} `
  }
  const capabilitiesArray = capabilities instanceof Set ? [...capabilities] : capabilities
  let caps = `\x00${capabilitiesArray.join(' ')} ${syms}agent=${pkg.agent}`
  // stream.write(GitPktLine.encode(`# service=${service}\n`))
  // stream.write(GitPktLine.flush())
  // Note: In the edge case of a brand new repo, zero refs (and zero capabilities)
  // are returned.
  const refsEntries = refs instanceof Map ? refs.entries() : Object.entries(refs)
  for (const [key, value] of refsEntries) {
    stream.push(GitPktLine.encode(`${value} ${key}${caps}\n`))
    caps = ''
  }
  stream.push(GitPktLine.flush())
  return stream
}



// ==============================================================================
// File: src\wire\writeUploadPackRequest.ts
// ==============================================================================

import { GitPktLine } from "../models/GitPktLine.ts"

export function writeUploadPackRequest({
  capabilities = [],
  wants = [],
  haves = [],
  shallows = [],
  depth = null,
  since = null,
  exclude = [],
}: {
  capabilities?: string[]
  wants?: string[]
  haves?: string[]
  shallows?: string[]
  depth?: number | null
  since?: Date | null
  exclude?: string[]
}): Buffer[] {
  const packstream: Buffer[] = []
  wants = [...new Set(wants)] // remove duplicates
  let firstLineCapabilities = ` ${capabilities.join(' ')}`
  for (const oid of wants) {
    packstream.push(GitPktLine.encode(`want ${oid}${firstLineCapabilities}\n`))
    firstLineCapabilities = ''
  }
  for (const oid of shallows) {
    packstream.push(GitPktLine.encode(`shallow ${oid}\n`))
  }
  if (depth !== null && depth !== undefined) {
    packstream.push(GitPktLine.encode(`deepen ${depth}\n`))
  }
  if (since !== null && since !== undefined) {
    packstream.push(
      GitPktLine.encode(`deepen-since ${Math.floor(since.valueOf() / 1000)}\n`)
    )
  }
  for (const oid of exclude) {
    packstream.push(GitPktLine.encode(`deepen-not ${oid}\n`))
  }
  packstream.push(GitPktLine.flush())
  for (const oid of haves) {
    packstream.push(GitPktLine.encode(`have ${oid}\n`))
  }
  packstream.push(GitPktLine.encode(`done\n`))
  return packstream
}



